"""Copy-free verification of the record 3-coloring of {1,...,76}."""
from typing import List, Optional, Tuple

COL_VEC: List[int] = [1,0,2,0,1,1,1,0,0,2,0,1,2,2,1,2,2,2,0,1,0,2,0,1,1,1,0,0,2,0,1,2,2,1,2,2,1,0,1,0,2,0,1,1,1,0,0,2,0,1,2,2,1,2,2,0,0,1,0,2,0,1,1,1,0,0,2,0,1,2,2,1,2,2,0,0]

def find_mono_copy(chi: List[int], N: int) -> Optional[Tuple[int, int]]:
    """Return (b, a) of the first monochromatic b, b+2a, b+5a in {1..N}, else None."""
    a = 1
    while 1 + 5 * a <= N:
        b = 1
        while b + 5 * a <= N:
            if chi[b - 1] == chi[b + 2 * a - 1] == chi[b + 5 * a - 1]:
                return (b, a)
            b += 1
        a += 1
    return None

if __name__ == "__main__":
    w = find_mono_copy(COL_VEC, 76)
    print("copy-free on {1..76}" if w is None else f"copy found at {w}")

"""Exhaustive small three-color homothety numbers G_3({0,p,q}) by brute force."""
from itertools import product
from typing import Optional, Tuple

def find_copy(assign: Tuple[int, ...], N: int, pat: Tuple[int, int, int]) -> bool:
    top = pat[-1]
    a = 1
    while 1 + top * a <= N:
        b = 1
        while b + top * a <= N:
            c = {assign[b + a * s - 1] for s in pat}
            if len(c) == 1:
                return True
            b += 1
        a += 1
    return False

def g3(pat: Tuple[int, int, int], max_N: int = 24) -> Optional[int]:
    for N in range(1, max_N + 1):
        if all(find_copy(list(a), N, pat) for a in product(range(3), repeat=N)):
            return N
    return None

if __name__ == "__main__":
    for pat in [(0, 1, 2), (0, 2, 4), (0, 1, 3)]:
        print(f"G_3({{{pat[0]},{pat[1]},{pat[2]}}}) = {g3(pat)}")
    # (0,2,5) itself is out of brute-force reach: G_3 = 77 (established separately)

"""Super-multiplicative lower bounds for G_r({0,2,5}) from the anchor G_3 = 77."""
from typing import Dict

def growth_table(g3: int = 77, upto: int = 12) -> Dict[int, int]:
    """Lower bounds G_{r} >= (G_a-1)(G_b-1)+1 built up from multiples of 3."""
    lb: Dict[int, int] = {3: g3}
    for r in range(6, upto + 1, 3):
        best = lb[r - 3]
        # combine 3 with (r-3): G_r >= (G_3-1)(G_{r-3}-1)+1
        best = max(best, (lb[3] - 1) * (lb[r - 3] - 1) + 1)
        lb[r] = best
    return lb

if __name__ == "__main__":
    for r, v in growth_table().items():
        print(f"G_{r}({{0,2,5}}) >= {v}")

