function VERIFY_COPY_FREE(chi, N, pattern={0,2,5}):
    top <- max(pattern)            # 5
    for a from 1 while 1 + top*a <= N:
        for b from 1 while b + top*a <= N:
            colors <- { chi[b + a*s] : s in pattern }
            if |colors| == 1:
                return (b, a)       # monochromatic copy found
    return NONE                     # copy-free

