function BUILD_CLAUSES(N, r, pattern={0,2,5}):
    vid(i,c) := (i-1)*r + c
    clauses <- []
    for i in 1..N:                         # totality
        clauses += [ OR_c x_{vid(i,c)} ]
    for a from 1 while 1 + max(pattern)*a <= N:
        for b from 1 while b + max(pattern)*a <= N:
            pts <- { b + a*s : s in pattern }
            for c in 0..r-1:               # avoidance
                clauses += [ OR_{p in pts} (NOT x_{vid(p,c)}) ]
    return (N*r, clauses)

function THRESHOLD_SWEEP(pattern, r, max_N):
    for N from 1 to max_N:
        if for EVERY r-coloring chi of {1..N}:
               VERIFY_COPY_FREE(chi, N, pattern) != NONE:
            return N               # first forced length = G_r
    return NONE
